        module.launch(
            "conv2d_ref",
            grid=(64, 32, 128),
            block=(16, 16, 1),
            arguments=[x, weight, b_arg, y, i32(has_bias)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

